334	const initializeResponses = (
335	  questions: Question[],
336	): QuestionnaireResponse[] => {
337	  const responses: QuestionnaireResponse[] = [];
338	
339	  const processQuestion = (q: Question) => {
340	    if (q.type === "group" && q.questions) {
341	      q.questions.forEach(processQuestion);
342	    } else {
343	      let defaultValues: ResponseValue[] = [];
344	      if (q.answer_option && q.answer_option.length > 0) {
345	        const defaultOptions: AnswerOption[] = q.answer_option.filter(
346	          (o) => o.initial_selected === true,
347	        );
348	        if (defaultOptions.length > 0) {
349	          defaultValues = defaultOptions.map((opt) => ({
350	            type: "string",
351	            value: opt.value,
352	            coding: opt.code ?? undefined,
353	          }));
354	        }
355	      }
356	      responses.push({
357	        question_id: q.id,
358	        link_id: q.link_id,
359	        values: defaultValues,
360	        structured_type: q.structured_type ?? null,
361	      });
362	    }
363	  };
364	
365	  questions.forEach(processQuestion);
366	  return responses;
367	};
