27	export function StructuredSlot({
28	  question,
29	  disabled,
30	}: {
31	  question: Question;
32	  disabled: boolean;
33	}) {
34	  const { t } = useTranslation();
35	  const { mode, subject, questionnaire } = useFormRenderer();
36	  const [response, updateResponse] = useQuestionResponse(question.id);
37	  const errors = useQuestionErrors(question.id);
38	
