40	    (values: ResponseValue[], _questionId: string, note?: string) =>
41	      updateResponse({ values, note }),
42	    [updateResponse],
43	  );
44	
45	  const entry = question.structured_type
46	    ? STRUCTURED_REGISTRY[question.structured_type]
47	    : undefined;
48	  if (!entry || !response) return null;
49	
50	  const missing = entry.requires.filter((key) => !subject[key]);
51	  if (missing.length > 0) {
52	    return (
53	      <div className="rounded-lg border border-dashed border-gray-300 bg-gray-50 p-4 text-sm text-gray-500">
