56	        </p>
57	        <p>
58	          {t("structured_question_requires_context", {
59	            contexts: missing.map((key) => t(`context__${key}`)).join(", "),
60	          })}
61	        </p>
62	      </div>
63	    );
64	  }
65	
66	  const Component = entry.component;
67	  return (
68	    <Component
69	      question={question}
70	      questionnaireResponse={response}
71	      updateQuestionnaireResponseCB={handleUpdate}
72	      disabled={disabled}
73	      errors={errors}
