4	
5	/**
6	 * The decoration seam: a host (the studio's edit canvas) wraps every
7	 * rendered question block with its own chrome — selection ring, floating
8	 * toolbar, click-to-select — without the renderer knowing the builder
9	 * exists. Preview/readonly/fill hosts provide no chrome and the renderer
10	 * output is exactly the plain form.
11	 */
12	export interface QuestionShellProps {
13	  question: Question;
14	  parentId: string | null;
15	  /** Position within the sibling list — drives move up/down affordances. */
16	  index: number;
17	  siblingCount: number;
18	  depth: number;
19	  number?: string;
20	  /** enable_when currently evaluates false (rendered only under
21	   *  `revealHidden`) — chrome shows a "hidden by conditions" cue. */
22	  hiddenByLogic: boolean;
23	  children: ReactNode;
24	}
25	
26	export interface FormChrome {
27	  /** Wraps each question block. Return `children` untouched to opt out at
28	   *  a given depth. */
29	  QuestionShell?: ComponentType<QuestionShellProps>;
30	  /** Rendered after the children of a group (`parentId` = group id) and
31	   *  after the top-level list (`parentId` = null) — the "add question
32	   *  here" affordance. */
33	  AppendZone?: ComponentType<{ parentId: string | null }>;
34	  /** Rendered in-flow inside each block, between the label/description and
35	   *  the input area (and under a section header) — the studio's logic and
36	   *  issue chips. */
37	  QuestionAnnotation?: ComponentType<{ question: Question }>;
38	}
39	
40	const ChromeContext = createContext<FormChrome>({});
41	
42	export function useFormChrome(): FormChrome {
